describe('Save Card Details for Future Purchases', () => {
  beforeEach(() => {
    cy.visit('/checkout');
  });

  it('should successfully save card details and display success message', () => {
    // Intercept the API call to save card details
    cy.intercept('POST', '/api/payment/save-card').as('saveCard');

    // Fill in card details
    cy.get('[data-testid="card-number-input"]').type('4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').type('1225');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Verify input fields are filled
    cy.get('[data-testid="card-number-input"]').should('have.value', '4111111111111111');
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '1225');
    cy.get('[data-testid="card-cvc-input"]').should('have.value', '123');

    // Click save button
    cy.get('[data-testid="save-card-button"]').click();

    // Wait for API response
    cy.wait('@saveCard');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Card details saved successfully');

    // Verify card details are stored
    cy.get('[data-testid="card-details-storage"]').should('be.visible');
    cy.get('[data-testid="card-details-storage"]').should('contain', '4111111111111111');

    // Verify card details are not visible on the form
    cy.get('[data-testid="card-number-input"]').should('not.have.value');
  });

  it('should handle invalid card details and display error message', () => {
    // Intercept the API call to save card details
    cy.intercept('POST', '/api/payment/save-card').as('saveCard');

    // Fill in invalid card details
    cy.get('[data-testid="card-number-input"]').type('1234');
    cy.get('[data-testid="card-expiry-input"]').type('00');
    cy.get('[data-testid="card-cvc-input"]').type('123');

    // Verify input fields are filled
    cy.get('[data-testid="card-number-input"]').should('have.value', '1234');
    cy.get('[data-testid="card-expiry-input"]').should('have.value', '00');
    cy.get('[data-testid="card-cvc-input"]').should('have.value', '123');

    // Click save button
    cy.get('[data-testid="save-card-button"]').click();

    // Wait for API response
    cy.wait('@saveCard');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid card details');

    // Verify card details are not stored
    cy.get('[data-testid="card-details-storage"]').should('not.exist');

    // Verify form is still visible
    cy.get('[data-testid="card-number-input"]').should('be.visible');
  });
});
